    pub(crate) fn server_code(status: u16, body: &[u8]) -> Option<ErrorCode> {
        if (200..300).contains(&status) || body.len() > MAX_ERROR_BODY_LEN {
            return None;
        }
        serde_json::from_slice::<ErrorResponse>(body).ok().map(|a| a.error)
    }
