    pub(crate) fn take_secret(bytes: &mut [u8])
        -> CoreResult<Zeroizing<String>> {
        let taken =
            core::str::from_utf8(bytes).map(|text|
                    Zeroizing::new(text.to_owned()));
        bytes.zeroize();
        taken.map_err(|_| ClientError::InvalidInput.into())
    }
